import UserList from './user/UserList';
import AlbumList from './Album/AlbumList'; // Asegúrate de que esta ruta sea correcta

function App() {
  return (
    <div className="container-fluid">
      <div className="container-fluid">
        <Menu />
      </div>
      <div className="container-fluid">

        <UserList />
        <AlbumList /> 
      </div>
      <div className="container-fluid">
        <Footer />
      </div>
    </div>
  );
}

export default App;
